#include <iostream>
#include <mutex>

class ParkingSpot {
public:
    bool tryOccupy() {                          // the only door in
        std::lock_guard<std::mutex> lock(mutex_);
        if (occupied_) return false;
        occupied_ = true;
        return true;
    }

private:
    bool occupied_ = false;                     // hidden state
    std::mutex mutex_;
};

int main() {
    ParkingSpot spot;
    std::cout << std::boolalpha;
    std::cout << spot.tryOccupy() << "\n";      // true
    std::cout << spot.tryOccupy() << "\n";      // false
    return 0;
}

