#include <iostream>

// capability: any class can promise this, no shared state
struct PaymentStrategy {
    virtual bool pay(int amount) = 0;
    virtual ~PaymentStrategy() = default;
};

// shared skeleton: children inherit fields and the chain logic
class NoteHandler {
public:
    virtual bool dispense(int amount) = 0;
    virtual ~NoteHandler() = default;

protected:
    int count = 0;                          // shared state lives here
    NoteHandler* next = nullptr;
};

class CashNoteHandler : public NoteHandler {
public:
    explicit CashNoteHandler(int c) { count = c; }
    bool dispense(int amount) override {
        if (count <= 0) return next != nullptr && next->dispense(amount);
        count--;
        return true;
    }
};

class CashPayment : public PaymentStrategy {
public:
    bool pay(int amount) override { return true; }
};

int main() {
    std::cout << std::boolalpha;
    CashPayment cash;
    std::cout << cash.pay(500) << "\n";

    CashNoteHandler handler(2);
    std::cout << handler.dispense(100) << "\n"; // true
    std::cout << handler.dispense(100) << "\n"; // true
    std::cout << handler.dispense(100) << "\n"; // false
    return 0;
}

