from abc import ABC, abstractmethod
from typing import Protocol, Optional


# capability: any class can promise this, no shared state
class PaymentStrategy(Protocol):
    def pay(self, amount: int) -> bool: ...


# shared skeleton: children inherit fields and the chain logic
class NoteHandler(ABC):
    def __init__(self):
        self.count = 0                       # shared state lives here
        self.next: Optional["NoteHandler"] = None

    @abstractmethod
    def dispense(self, amount: int) -> bool: ...


class CashNoteHandler(NoteHandler):
    def __init__(self, count: int):
        super().__init__()
        self.count = count

    def dispense(self, amount: int) -> bool:
        if self.count <= 0:
            return self.next is not None and self.next.dispense(amount)
        self.count -= 1
        return True


class CashPayment:
    def pay(self, amount: int) -> bool:
        return True


if __name__ == "__main__":
    cash: PaymentStrategy = CashPayment()
    print(cash.pay(500))

    handler = CashNoteHandler(2)
    print(handler.dispense(100))  # True
    print(handler.dispense(100))  # True
    print(handler.dispense(100))  # False, out of notes and no next
